15	func init() {
16		Register(&NexusDetector{})
17	}
18	
19	// NexusDetector handles Sonatype Nexus Repository Manager group repositories.
20	// Two URL formats are supported:
21	//  1. Path-based:   https://nexus.example.com/repository/docker-group  (auto-detected)
22	//  2. Subdomain:    nexus-docker-group.example.com  (requires info.NexusURL to be set)
23	type NexusDetector struct{}
24	
25	var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second}
26	
27	// CanHandle returns true when:
28	//   - the registry URL contains the Nexus "/repository/" path segment, OR
29	//   - info.ManagementURL is explicitly set (subdomain connector case)
30	func (n *NexusDetector) CanHandle(info RegistryInfo) bool {
31		if info.ManagementURL != "" {
32			return true
33		}
34		return strings.Contains(info.URL, "/repository/")
35	}
36	
37	// DetectGroup calls the Nexus REST API to determine whether the registry points
38	// to a group repository and, if so, returns its member repositories.
39	// Returns nil, nil when the repository exists but is not a group.
40	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
41		// Resolve which URL to use for the Nexus API call.
42		apiBase := info.ManagementURL
43		if apiBase == "" {
44			apiBase = info.URL
45		}
46	
47		host, repoName, err := parseNexusURL(apiBase)
48		if err != nil {
49			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL %q: %v", apiBase, err)
50			return nil, nil
51		}
52	
53		hasAuth := info.Username != "" && info.Password != ""
54		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
55	
56		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
57		// and may already include memberNames in the attributes field (no admin privilege needed).
58		repoType, repoFormat, members, ok := n.fetchRepoMeta(ctx, host, repoName, info)
59		if !ok || repoType != "group" {
60			return nil, nil
61		}
62	
63		if len(members) > 0 {
64			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
65			return members, nil
66		}
67	
68		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
69		// but returns memberNames reliably on Nexus instances that support it.
70		members = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
71		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
72		return members, nil
73	}
74	
75	// fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
76	// Returns type, format, any memberNames found in attributes, and whether the call succeeded.
77	// Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
78	func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, ok bool) {
79		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
80		body, err := n.nexusGET(ctx, endpoint, info)
81		if err != nil {
82			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
83			return "", "", nil, false
84		}
85		var result struct {
86			Type   string `json:"type"`
87			Format string `json:"format"`
88			Group  struct {
89				MemberNames []string `json:"memberNames"`
90			} `json:"group"`
91			Attributes struct {
92				Group struct {
93					MemberNames []string `json:"memberNames"`
94				} `json:"group"`
95			} `json:"attributes"`
96		}
97		if err := json.Unmarshal(body, &result); err != nil {
98			log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
99			return "", "", nil, false
100		}
101		log.Printf("INFO [registrymgr/nexus] meta %q: type=%s format=%s", repoName, result.Type, result.Format)
102	
103		// Collect memberNames from whichever field Nexus populated.
104		rawNames := result.Group.MemberNames
105		if len(rawNames) == 0 {
106			rawNames = result.Attributes.Group.MemberNames
107		}
108		for _, name := range rawNames {
109			members = append(members, GroupMember{
110				Alias: cleanMemberAlias(name),
111				URL:   fmt.Sprintf("%s/repository/%s", host, name),
112			})
113		}
114		return result.Type, result.Format, members, true
115	}
116	
117	// fetchGroupMembers calls the format-specific group endpoint which reliably
118	// includes memberNames: GET /v1/repositories/{format}/group/{name}
119	// Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
120	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember {
121		if format == "" {
122			format = "docker"
123		}
124		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, format, repoName)
125		body, err := n.nexusGET(ctx, endpoint, info)
126		if err != nil {
127			// When auth is present but the request fails, retry anonymously.
128			// Some Nexus instances allow anonymous read of the group admin endpoint.
129			if info.Username != "" && info.Password != "" {
130				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
131				body, err = n.nexusGET(ctx, endpoint, anonInfo)
132			}
133		}
134		if err != nil {
135			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
136			return nil
137		}
138		var result struct {
139			Group struct {
140				MemberNames []string `json:"memberNames"`
141			} `json:"group"`
142		}
143		if err := json.Unmarshal(body, &result); err != nil {
144			return nil
145		}
146		members := make([]GroupMember, 0, len(result.Group.MemberNames))
147		for _, name := range result.Group.MemberNames {
148			members = append(members, GroupMember{
149				Alias: cleanMemberAlias(name),
150				URL:   fmt.Sprintf("%s/repository/%s", host, name),
151			})
152		}
153		return members
154	}
155	
156	// nexusGET performs an authenticated GET and returns the response body.
157	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
158		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
159		if err != nil {
160			return nil, err
161		}
162		if info.Username != "" && info.Password != "" {
163			req.SetBasicAuth(info.Username, info.Password)
164		}
165		resp, err := nexusHTTPClient.Do(req)
166		if err != nil {
167			return nil, err
168		}
169		defer func() { _ = resp.Body.Close() }()
170		if resp.StatusCode != http.StatusOK {
171			return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
172		}
173		var buf []byte
174		buf, err = io.ReadAll(resp.Body)
175		return buf, err
176	}
177	
178	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
179	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
180	func parseNexusURL(registryURL string) (host, repoName string, err error) {
181		raw := registryURL
182		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
183			raw = "https://" + raw
184		}
185		u, err := url.Parse(raw)
186		if err != nil {
187			return "", "", err
188		}
189		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
190		// Expected: ["repository", "<repoName>", ...]
191		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
192			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
193		}
194		host = u.Scheme + "://" + u.Host
195		repoName = parts[1]
196		return host, repoName, nil
197	}
198	
199	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
200	func cleanMemberAlias(name string) string {
201		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
202			if strings.HasSuffix(name, suffix) {
203				return name[:len(name)-len(suffix)]
204			}
205		}
206		return name
207	}
