66	// RegistryLogin authenticates with a Docker/OCI registry using `docker login`.
67	// The password is passed via stdin to avoid exposing it in the process list.
68	func RegistryLogin(registryURL, username, password string) error {
69		if err := requireDocker(); err != nil {
70			return err
71		}
72		output, err := runner.Run(dockerCmd{
73			Args:     []string{"login", registryURL, "-u", username, "--password-stdin"},
74			Stdin:    password,
75			Combined: true,
76		})
77		if err != nil {
78			return errWithOutput("docker login", output)
79		}
80		return nil
81	}
82	
83	// IsRegistryLoggedIn reports whether stored credentials exist for registryURL
84	// by inspecting ~/.docker/config.json.
85	func IsRegistryLoggedIn(registryURL string) bool {
86		var cfg struct {
87			Auths map[string]json.RawMessage `json:"auths"`
88		}
89		if err := readDockerConfig(&cfg); err != nil {
90			return false
91		}
92		for _, c := range registryCandidates(registryURL) {
93			if _, ok := cfg.Auths[c]; ok {
94				return true
95			}
96		}
97		return false
98	}
99	
100	// RegistryLogout removes stored credentials for a Docker/OCI registry.
101	// It runs `docker logout` (cleans system credential stores) then directly
102	// removes all matching keys from ~/.docker/config.json to handle cases where
103	// docker logout leaves behind alias entries (e.g. docker.io vs https://index.docker.io/v1/).
104	func RegistryLogout(registryURL string) error {
105		if err := requireDocker(); err != nil {
106			return err
107		}
108		if err := mutate("docker logout", "logout", registryURL); err != nil {
109			return err
110		}
111		// Also remove all matching alias keys directly from config.json.
112		_ = removeFromDockerConfig(registryURL)
113		return nil
114	}
115	
116	// removeFromDockerConfig removes all URL variants of registryURL from the auths
117	// section of ~/.docker/config.json. Errors are non-fatal (best effort).
118	func removeFromDockerConfig(registryURL string) error {
119		configPath, err := dockerConfigPath()
120		if err != nil {
121			return err
122		}
123	
124		var raw map[string]json.RawMessage
125		if err := readDockerConfig(&raw); err != nil {
126			return err
127		}
128		authsRaw, ok := raw["auths"]
129		if !ok {
130			return nil
131		}
132		var auths map[string]json.RawMessage
133		if err := json.Unmarshal(authsRaw, &auths); err != nil {
134			return err
135		}
136	
137		changed := false
138		for _, candidate := range registryCandidates(registryURL) {
139			if _, exists := auths[candidate]; exists {
140				delete(auths, candidate)
141				changed = true
142			}
143		}
144		if !changed {
145			return nil
146		}
147	
148		updated, err := json.Marshal(auths)
149		if err != nil {
150			return err
151		}
152		raw["auths"] = updated
153		out, err := json.MarshalIndent(raw, "", "\t")
154		if err != nil {
155			return err
156		}
157		return os.WriteFile(configPath, out, 0600)
158	}
159	
160	// GetStoredCreds retrieves Docker credentials for registryURL from
161	// ~/.docker/config.json. It tries the per-registry credential helper
162	// (credHelpers), then the global credsStore, and finally falls back to the
163	// inline base64-encoded auth field. Returns ok=false when no credentials are
164	// found.
165	func GetStoredCreds(registryURL string) (username, password string, ok bool) {
166		var cfg struct {
167			Auths map[string]struct {
168				Auth string `json:"auth"`
169			} `json:"auths"`
170			CredsStore  string            `json:"credsStore"`
171			CredHelpers map[string]string `json:"credHelpers"`
172		}
173		if err := readDockerConfig(&cfg); err != nil {
174			return "", "", false
175		}
176	
177		// Normalise the URL to a bare hostname for helper lookups.
178		hostname := strings.TrimSuffix(registryURL, "/")
179		for _, prefix := range []string{"https://", "http://"} {
180			hostname = strings.TrimPrefix(hostname, prefix)
181		}
182	
183		helper := cfg.CredHelpers[hostname]
184		if helper == "" {
185			helper = cfg.CredsStore
186		}
187		if helper != "" {
188			if u, p, ok := getCredsFromHelper(helper, hostname); ok {
189				return u, p, true
190			}
191		}
192	
193		for _, candidate := range registryCandidates(registryURL) {
194			if entry, ok := cfg.Auths[candidate]; ok && entry.Auth != "" {
195				if u, p, ok := decodeAuth(entry.Auth); ok {
196					return u, p, true
197				}
198			}
199		}
200		return "", "", false
201	}
202	
203	// decodeAuth splits a base64 "username:password" auth field.
204	func decodeAuth(auth string) (username, password string, ok bool) {
205		decoded, err := base64.StdEncoding.DecodeString(auth)
206		if err != nil {
207			return "", "", false
208		}
209		if idx := strings.IndexByte(string(decoded), ':'); idx >= 0 {
210			return string(decoded[:idx]), string(decoded[idx+1:]), true
211		}
212		return "", "", false
213	}
214	
215	// getCredsFromHelper calls `docker-credential-<helper> get` and parses the JSON response.
216	func getCredsFromHelper(helper, serverURL string) (username, password string, ok bool) {
217		out, err := runner.Run(dockerCmd{
218			Args:   []string{"get"},
219			Stdin:  serverURL,
220			Helper: helper,
221		})
222		if err != nil {
223			return "", "", false
224		}
225		var result struct {
226			Username string `json:"Username"`
227			Secret   string `json:"Secret"`
228		}
229		if err := json.Unmarshal(out, &result); err != nil {
230			return "", "", false
231		}
232		if result.Secret == "" {
233			return "", "", false
234		}
235		return result.Username, result.Secret, true
236	}
237	
238	// RegistryAlias pairs a URL prefix with a short alias for display purposes.
239	type RegistryAlias struct {
240		URL   string
241		Alias string
242	}
243	
244	// ApplyAliases replaces registry URL prefixes in an image name with their configured alias.
245	// Example: URL="gitlab.com/my-group", Alias="gl" turns
246	// "gitlab.com/my-group/my-image:1.0" into "gl/my-image:1.0".
247	func ApplyAliases(imageName string, aliases []RegistryAlias) string {
248		for _, a := range aliases {
249			if a.Alias == "" || a.URL == "" {
250				continue
251			}
252			prefix := strings.TrimSuffix(a.URL, "/") + "/"
253			if strings.HasPrefix(imageName, prefix) {
254				return a.Alias + "/" + strings.TrimPrefix(imageName, prefix)
255			}
256		}
257		return imageName
258	}
