208	// finalizeEntries flattens entryGroups into entries, initialises selectedRegs (all checked),
209	// and transitions the browser to the input form state.
210	func (b *RegistryBrowser) finalizeEntries() {
211		b.entries = nil
212		for _, group := range b.entryGroups {
213			b.entries = append(b.entries, group...)
214		}
215		b.selectedRegs = make(map[string]bool, len(b.entries))
216		for _, e := range b.entries {
217			b.selectedRegs[e.URL] = true
218		}
219		b.state = browserStateInput
220		b.updateFocus()
221	}
