279	// Update handles all messages for the browser.
280	func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
281		switch msg := msg.(type) {
282		case tea.KeyMsg:
283			return b.handleKeyMsg(msg)
284		case spinner.TickMsg:
285			if b.state == browserStateStatus || b.state == browserStateResolving || len(b.scanningTags) > 0 || b.pendingSearches > 0 {
286				var cmd tea.Cmd
287				b.spinner, cmd = b.spinner.Update(msg)
288				if b.state == browserStateTags && len(b.scanningTags) > 0 {
289					b.tagScanSpinnerIdx++
290					b.rebuildTagTable()
291				}
292				return b, cmd
293			}
294			return b, nil
295		}
296		return b.delegateUpdate(msg)
297	}
298	
299	func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
300		if b.state == browserStateInput && b.focusedField == brFieldRepo {
301			var cmd tea.Cmd
302			b.repoInput, cmd = b.repoInput.Update(msg)
303			return b, cmd
304		}
305		if b.state == browserStateTags {
306			if b.filterActive {
307				var cmd tea.Cmd
308				b.filterInput, cmd = b.filterInput.Update(msg)
309				b.rebuildTagTable()
310				return b, cmd
311			}
312			var cmd tea.Cmd
313			b.tagTable, cmd = b.tagTable.Update(msg)
314			return b, cmd
315		}
316		return b, nil
317	}
318	
319	func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
320		switch b.state {
321		case browserStateResolving:
322			return b, nil
323		case browserStateInput:
324			return b.handleInputKeyMsg(msg)
325		case browserStateTags:
326			return b.handleTagsKeyMsg(msg)
327		case browserStateStatus:
328			return b, nil
329		}
330		return b, nil
331	}
332	
333	func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
334		switch msg.String() {
335		case "esc":
336			return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
337		case "down":
338			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
339			b.updateFocus()
340			return b, nil
341		case "up":
342			b.focusedField = max(b.focusedField-1, brFieldRepo)
343			b.updateFocus()
344			return b, nil
345		case " ":
346			if b.focusedField >= 1 && b.focusedField <= len(b.entries) {
347				url := b.entries[b.focusedField-1].URL
348				b.selectedRegs[url] = !b.selectedRegs[url]
349				return b, nil
350			}
351		case "enter":
352			if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
353				return b.submitSearch()
354			}
355			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
356			b.updateFocus()
357			return b, nil
358		}
359		return b.delegateUpdate(msg)
360	}
