362	func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
363		repo := strings.TrimSpace(b.repoInput.Value())
364		if repo == "" {
365			return b, nil
366		}
367	
368		b.tags = nil
369		b.registryFilter = ""
370		b.pendingSearches = 0
371		b.filterInput.SetValue("")
372		b.filterActive = false
373		b.tagSortCol = tagSortByName
374		b.tagSortDesc = false
375	
376		var cmds []tea.Cmd
377		for _, entry := range b.entries {
378			if !b.selectedRegs[entry.URL] {
379				continue
380			}
381			// Credentials come from the parent registry (or the entry itself for normal registries).
382			credURL := entry.URL
383			if entry.parentURL != "" {
384				credURL = entry.parentURL
385			}
386			var username string
387			for _, reg := range b.registries {
388				if reg.URL == credURL {
389					username = reg.Username
390					break
391				}
392			}
393			storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
394			if username == "" {
395				username = storedUser
396			}
397			alias := entry.Alias
398			if entry.ParentAlias != "" {
399				alias = entry.ParentAlias + "/" + entry.Alias
400			}
401			normalizedRepo := normalizeRepoForRegistry(entry.URL, repo)
402			apiURL := registryAPIURL(entry.URL)
403			b.pendingSearches++
404			cmds = append(cmds, searchRegistryTagsCmd(entry.URL, alias, apiURL, normalizedRepo, username, storedPass))
405		}
406	
407		if len(cmds) == 0 {
408			return b, nil
409		}
410	
411		b.state = browserStateTags
412		b.tagTable.Focus()
413		b.rebuildTagTable()
414		cmds = append(cmds, b.spinner.Tick)
415		return b, tea.Batch(cmds...)
416	}
417	
418	func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
419		if b.filterActive {
420			switch msg.String() {
421			case "esc", "enter":
422				b.filterActive = false
423				b.filterInput.Blur()
424				b.rebuildTagTable()
425				b.resizeTagTable()
426				return b, nil
427			}
428			return b.delegateUpdate(msg)
429		}
430	
431		switch msg.String() {
432		case "esc":
433			b.state = browserStateInput
434			b.tagTable.Blur()
435			b.updateFocus()
436			return b, nil
437		case "/":
438			b.filterActive = true
439			b.filterInput.Focus()
440			b.resizeTagTable()
441			return b, nil
442		case ".":
443			b.cycleSortTags()
444			return b, nil
445		case "r":
446			b.cycleRegistryFilter()
447			return b, nil
448		case "up", "k":
449			b.tagTable.MoveUp(1)
450			return b, nil
451		case "down", "j":
452			b.tagTable.MoveDown(1)
453			return b, nil
454		case "g", "home":
455			b.tagTable.GotoTop()
456			return b, nil
457		case "G", "end":
458			b.tagTable.GotoBottom()
459			return b, nil
460		case "enter":
461			return b.openTagScanDetails()
462		case "p":
463			return b.pullSelectedTag()
464		case "ctrl+s":
465			return b.requestDirectScan()
466		}
467		return b, nil
468	}
