	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ociTab represents the active tab in the OCI resources view
type ociTab int

const (
	tabImages     ociTab = iota
	tabNetworks          // Networks tab
	tabVolumes           // Volumes tab
	tabRegistries        // Registries tab
)

// sortField defines which column to sort by
type sortField int

const (
	sortByName sortField = iota
	sortByDiskUsage
	sortByContentSize
	sortByCritical
	sortByHigh
	sortByMedium
	sortByLow
	sortByScanned
)

// Model represents the OCI resources view state
type Model struct {
	config    *config.Config
	activeTab ociTab
	// Images tab
	images          []docker.Image
	scanCache       map[string]cache.ImageScanEntry
	scanningImages  map[string]bool
	failedScans     map[string]bool
	spinnerFrameIdx int
	lastScanOptions scan.ScanOptions
	filterBar       sharedcomponents.FilterBar
	imageTable      table.Model
	spinner         spinner.Model
	loading         bool
	scanning        bool
	// Networks tab
	networks     []docker.Network
	networkTable table.Model
	loadingNets  bool
	// Volumes tab
	volumes     []docker.Volume
	volumeTable table.Model
	loadingVols bool
	// Registries tab
	registries          []config.RegistryItem
	registryTable       table.Model
	loadingRegs         bool
	registryForm        *RegistryForm
	registryBrowser     *RegistryBrowser
	registryLoginStatus map[string]bool // URL → logged in
	// launch options pending save — set on submit, cleared after successful or failed launch
	lastLaunchImage string
	lastLaunchOpts  *cache.LaunchOptionsEntry
	// Forms (viewport-based, Rule 112)
	launchForm         *LaunchForm
	resourceForm       *ResourceCreateForm
	networkInspectForm *NetworkInspectForm
	connectivityForm   *ConnectivityTestForm
	// Shared state
	errorMsg         string
	infoMsg          string
	confirmModal     *sharedcomponents.ConfirmModal
	pendingAction    string
	sortColumn       sortField
	sortAsc          bool
	width, height    int
	selectionMode    bool
	selectionMessage string
}

// Messages — Images

// ImageScanStartingMsg signals that scanning is starting for a single image
type ImageScanStartingMsg struct {
	ImageName string
}

// ImageScanFinishedMsg signals that scanning has completed for a single image
type ImageScanFinishedMsg struct {
	ImageName string
	Entry     cache.ImageScanEntry
	Err       error
}

// RefreshTickMsg triggers periodic refresh
type RefreshTickMsg time.Time

// ImagesListMsg contains fetched images
type ImagesListMsg struct {
	Images []docker.Image
	Err    error
}

// ImageActionMsg signals result of an image action (remove)
type ImageActionMsg struct {
	Action string
	ID     string
	Err    error

	m.imageTable.SetHeight(m.tableHeight())
}

// updateNetworkTable rebuilds the network table rows
func (m *Model) updateNetworkTable() {
	rows := make([]table.Row, 0, len(m.networks))
	for _, net := range m.networks {
		shortID := net.ID
		if len(shortID) > 12 {
			shortID = shortID[:12]
		}
		rows = append(rows, table.Row{shortID, net.Name, net.Driver, net.Scope})
	}
	m.networkTable.SetRows(rows)
	m.networkTable.SetStyles(theme.DefaultTableStyles())
	m.networkTable.SetHeight(m.tableHeight())
}

// updateVolumeTable rebuilds the volume table rows
func (m *Model) updateVolumeTable() {
	rows := make([]table.Row, 0, len(m.volumes))
	for _, vol := range m.volumes {
		rows = append(rows, table.Row{vol.Name, vol.Driver, vol.Mountpoint})
	}
	m.volumeTable.SetRows(rows)
	m.volumeTable.SetStyles(theme.DefaultTableStyles())
	m.volumeTable.SetHeight(m.tableHeight())
}

// updateRegistryTable rebuilds the registry table rows
func (m *Model) updateRegistryTable() {
	rows := make([]table.Row, 0, len(m.registries))
	for _, reg := range m.registries {
		auth := "no"
		if reg.AuthEnabled {
			auth = "yes"
		}
		logged := "-"
		if reg.AuthEnabled {
			if m.registryLoginStatus[reg.URL] {
				logged = theme.IconOK
			} else {
				logged = theme.IconError
